    p[-2]=last+' '+text+' '
    lines[i]='|'.join(p); save(lines)
def set_status(n,text):
    lines=load(); i=find(lines,n); p=cells(lines[i])
    p[3]=' '+text+' '
    lines[i]='|'.join(p); save(lines)
