    lines=load(); i=find(lines,n); p=cells(lines[i])
    p[k+1]=' '+text+' '
    lines[i]='|'.join(p); save(lines)
def insert_after(n,rowline):
    lines=load(); i=find(lines,n)
    lines.insert(i+1,rowline); save(lines)
if __name__=='__main__':
